'use strict';

// Builds the two n8n Code-node scripts for the demo-prompt workflow (docs/15) from the single
// source of truth in demo-kit/: kits/*.json, master-prompt.template.md and lib/demo-kit.js.
// The generated files in demo-kit/n8n/ are pasted into n8n Code nodes ("Run Once for All Items").
// Usage: npm run build:demo-kit   (tests/demo-kit.test.js fails if the generated files are stale)

const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const kitDir = path.join(root, 'demo-kit');

function readKits() {
  const dir = path.join(kitDir, 'kits');
  const kits = {};
  for (const file of fs.readdirSync(dir).filter((f) => f.endsWith('.json')).sort()) {
    const kit = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    kits[kit.id] = kit;
  }
  return kits;
}

function buildScripts() {
  const kits = readKits();
  const template = fs.readFileSync(path.join(kitDir, 'master-prompt.template.md'), 'utf8').replace(/\r\n/g, '\n');
  const lib = fs.readFileSync(path.join(kitDir, 'lib', 'demo-kit.js'), 'utf8').replace(/\r\n/g, '\n');
  const header = (title) =>
    `// GENERATED by scripts/build-demo-kit.js from demo-kit/. Do not edit here: edit the source files and run \`npm run build:demo-kit\`.\n` +
    `// n8n Code node: ${title}. Mode: "Run Once for All Items", language JavaScript.\n\n`;
  const data = `const KITS = ${JSON.stringify(kits)};\nconst TEMPLATE = ${JSON.stringify(template)};\nconst PREVIEW_BASE_URL = 'https://preview.synergyfirstdigital.com';\n\n`;

  const one = header('1 "Prepare AI request" (after the "Fetch website" HTTP Request node)') + data + lib + `
// ---------------------------------------------------------------- node 1
const OPENAI_MODEL = 'gpt-4.1-mini'; // change here if you prefer another model

const lead = $('Webhook').first().json.body;
const fetched = $input.first().json; // output of the "Fetch website" node (response format: text)
const html = typeof fetched.data === 'string' ? fetched.data : '';

const research = extractResearch(html, lead.website);
const kitId = pickKitId(lead.trade, KITS);
const kit = KITS[kitId];

return [
  {
    json: {
      token: makeToken(),
      kitId,
      expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
      lead: {
        businessName: lead.businessName,
        website: lead.website,
        services: lead.services,
        message: lead.message,
        trade: lead.trade,
        reference: lead.reference,
      },
      research,
      openaiBody: buildAiRequest({ lead, research, kit, model: OPENAI_MODEL }),
    },
  },
];
`;

  const two = header('2 "Build master prompt" (after the OpenAI HTTP Request node)') + data + lib + `
// ---------------------------------------------------------------- node 2
const prev = $('Prepare AI request').first().json;
const reply = $input.first().json; // OpenAI chat completion
const content = reply.choices && reply.choices[0] && reply.choices[0].message ? reply.choices[0].message.content : '{}';

const kit = KITS[prev.kitId];
const ai = parseAi(content, kit);
const { prompt, values, missing } = renderPrompt({
  lead: prev.lead,
  research: prev.research,
  ai,
  kit,
  token: prev.token,
  expiresAtIso: prev.expiresAt,
  previewBaseUrl: PREVIEW_BASE_URL,
  template: TEMPLATE,
});

const fileName = 'demo-prompt-' + prev.token + '.md';
const data = await this.helpers.prepareBinaryData(Buffer.from(prompt, 'utf8'), fileName, 'text/markdown');

const summary = [
  'Demo prompt ready: ' + prev.lead.businessName,
  'Kit: ' + kit.label + ' | ' + ai.palette.name + ' | ' + ai.font.name,
  'Upload folder: ' + prev.token,
  'Preview URL: ' + values.previewUrl,
  'Expires: ' + values.expiresDisplay,
  'To confirm with the business: ' + missing.length + ' items (listed in the prompt)',
  prev.research && prev.research.ok ? 'Website text was read.' : 'No website text (Google profile link or fetch failed): facts come from the form only.',
].join('\\n');

return [
  {
    json: { token: prev.token, previewUrl: values.previewUrl, expiresAt: prev.expiresAt, kit: kit.id, palette: ai.palette.id, fontPair: ai.font.id, fileName, summary },
    binary: { data },
  },
];
`;
  return { '1-prepare-ai-request.js': one, '2-build-prompt.js': two };
}

function writeScripts() {
  const outDir = path.join(kitDir, 'n8n');
  fs.mkdirSync(outDir, { recursive: true });
  const files = buildScripts();
  for (const [name, content] of Object.entries(files)) {
    fs.writeFileSync(path.join(outDir, name), content, 'utf8');
  }
  return Object.keys(files).map((n) => path.join('demo-kit', 'n8n', n));
}

module.exports = { buildScripts, readKits };

if (require.main === module) {
  console.log('Wrote:\n  ' + writeScripts().join('\n  '));
}
